# Floyd 扩展求最小环（无向图，可记录路径）
ans = INF
for k in 1..n:
    # 先用当前 dis 更新环（i<j<k）
    for i in 1..k-1:
        for j in 1..i-1:
            if val[i][k]+val[k][j]+dis[i][j] < ans:
                ans = ...; 记录环: i,k,j + 递归展开 dis[j][i] 的中间点
    # 再正常 Floyd 松弛
    for i in 1..n:
        for j in 1..n:
            if dis[i][k]+dis[k][j] < dis[i][j]:
                dis[i][j] = ...; pos[i][j] = k
